INSERT INTO counterparties (identity_type, identity_value, display_name) SELECT identity_type, identity_value, (array_agg( normalized_display ORDER BY booking_date DESC, counterparty_name ASC, content_hash ASC, occurrence_index ASC ) FILTER (WHERE normalized_display <> ''))[1] AS display_name FROM ( SELECT CASE WHEN attributed_name IS NOT NULL THEN 'name' WHEN creditor_id IS NOT NULL THEN 'creditor_id' WHEN counterparty_iban IS NOT NULL THEN 'iban' WHEN normalized_name <> '' THEN 'name' END AS identity_type, CASE WHEN attributed_name IS NOT NULL THEN upper(normalized_attributed) WHEN creditor_id IS NOT NULL THEN creditor_id WHEN counterparty_iban IS NOT NULL THEN counterparty_iban WHEN normalized_name <> '' THEN upper(normalized_name) END AS identity_value, counterparty_name, normalized_display, booking_date, content_hash, occurrence_index FROM ( SELECT creditor_id, counterparty_iban, counterparty_name, attributed_name, trim(regexp_replace( normalize(counterparty_name, NFC), '\s+', ' ', 'g' )) AS normalized_name, trim(regexp_replace( normalize(attributed_name, NFC), '\s+', ' ', 'g' )) AS normalized_attributed, trim(regexp_replace( normalize(COALESCE(attributed_name, counterparty_name), NFC), '\s+', ' ', 'g' )) AS normalized_display, booking_date, content_hash, occurrence_index FROM transactions WHERE split_parent_content_hash IS NULL ) normalized ) identified WHERE identity_type IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM counterparty_alias a WHERE a.identity_type = identified.identity_type AND a.identity_value = identified.identity_value ) GROUP BY identity_type, identity_value ON CONFLICT (identity_type, identity_value) DO NOTHING
